package org.apache.accumulo.test.ample.metadata;

import java.util.Map;

import org.apache.accumulo.core.conf.SiteConfiguration;
import org.apache.accumulo.core.metadata.schema.Ample;
import org.apache.accumulo.core.metadata.schema.Ample.DataLevel;
import org.apache.accumulo.server.ServerContext;

/**
 * A test-only {@link ServerContext} that returns an {@link Ample} backed by {@link TestAmple} using
 * a {@link FlakyInterceptor}. This causes conditional mutations against the (real) metadata and root
 * tables to have ambiguous outcomes, exercising code paths that must tolerate not knowing whether a
 * conditional mutation was applied.
 */
public class FlakyAmpleServerContext extends ServerContext {

  public FlakyAmpleServerContext(SiteConfiguration siteConfig) {
    super(siteConfig);
  }

  @Override
  public Ample getAmple() {
    // Map the metadata levels to the real production tables so mutations go through the normal
    // metadata/root tables, but wrap the conditional writer with a FlakyInterceptor.
    Map<DataLevel,String> tables = Map.of(DataLevel.METADATA, DataLevel.METADATA.metaTable(),
        DataLevel.USER, DataLevel.USER.metaTable());
    return TestAmple.create(this, tables, FlakyInterceptor::new);
  }
}
