package org.apache.accumulo.test;

import org.apache.accumulo.core.client.Accumulo;
import org.apache.accumulo.core.client.AccumuloClient;
import org.apache.accumulo.harness.SharedMiniClusterBase;
import org.apache.accumulo.minicluster.ServerType;
import org.apache.accumulo.test.ample.metadata.FlakyAmpleManager;
import org.apache.accumulo.test.ample.metadata.FlakyAmpleTserver;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;

/**
 * This test runs the comprehensive test suite against a cluster whose manager and tablet servers use
 * a {@link org.apache.accumulo.test.ample.metadata.FlakyInterceptor}, which causes conditional
 * mutations against the metadata tables to have ambiguous outcomes. This exercises Accumulo's ability
 * to tolerate not knowing whether a conditional metadata mutation was applied.
 */
public class ComprehensiveFlakyAmpleIT extends ComprehensiveBaseIT {

  @BeforeAll
  public static void setup() throws Exception {
    SharedMiniClusterBase.startMiniClusterWithConfig((cfg, coreSite) -> {
      cfg.setServerClass(ServerType.MANAGER, FlakyAmpleManager.class);
      cfg.setServerClass(ServerType.TABLET_SERVER, FlakyAmpleTserver.class);
    });

    try (AccumuloClient client = Accumulo.newClient().from(getClientProps()).build()) {
      client.securityOperations().changeUserAuthorizations("root", AUTHORIZATIONS);
    }
  }

  @AfterAll
  public static void teardown() {
    SharedMiniClusterBase.stopMiniCluster();
  }
}
